87	/// A single diagnostic: the duplicate rule's range and the first occurrence's range.
88	#[derive(Debug)]
89	pub struct DuplicateSelectorList {
90	    /// Range of the rule whose selector list is a duplicate.
91	    duplicate_range: TextRange,
92	    /// Range of the first rule with this selector list.
93	    first_range: TextRange,
94	    /// Normalized selector list (for the diagnostic message).
95	    normalized_list: String,
96	}
