98	impl Rule for NoDuplicateSelectors {
99	    type Query = Semantic<AnyCssRoot>;
100	    type State = DuplicateSelectorList;
101	    type Signals = Box<[Self::State]>;
102	    type Options = NoDuplicateSelectorsOptions;
103	
104	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
105	        let model = ctx.model();
106	        let root = ctx.root();
107	
108	        // Maps (at_rule_context, normalized_selector_list_key) → first occurrence range.
109	        let mut seen: FxHashMap<(Vec<RuleId>, String), TextRange> = FxHashMap::default();
110	        let mut duplicates: Vec<DuplicateSelectorList> = Vec::new();
111	        let mut visited: FxHashSet<RuleId> = FxHashSet::default();
112	
113	        // Iterative DFS using an explicit stack with sentinel frames for context pop.
114	        enum Frame {
115	            Visit(RuleId),
116	            /// Sentinel: pop one entry from `at_rule_context` after a subtree is done.
117	            PopAtRule,
118	        }
119	
120	        let mut at_rule_context: Vec<RuleId> = Vec::new();
121	        // Seed the stack with all top-level rules (reversed so they process in order).
122	        let mut stack: Vec<Frame> = model
123	            .rules()
124	            .iter()
125	            .rev()
126	            .map(|r| Frame::Visit(r.id()))
127	            .collect();
128	
129	        while let Some(frame) = stack.pop() {
130	            match frame {
131	                Frame::PopAtRule => {
132	                    at_rule_context.pop();
133	                }
134	                Frame::Visit(rule_id) => {
135	                    let rule = match model.get_rule_by_id(&rule_id) {
136	                        Some(r) => r,
137	                        None => continue,
138	                    };
139	
140	                    if !visited.insert(rule.id()) {
141	                        continue;
142	                    }
143	
144	                    let is_at_rule = matches!(
145	                        rule.node(&root),
146	                        AnyRuleStart::CssMediaAtRule(_)
147	                            | AnyRuleStart::CssSupportsAtRule(_)
148	                            | AnyRuleStart::CssContainerAtRule(_)
149	                            | AnyRuleStart::CssStartingStyleAtRule(_)
150	                    );
151	
152	                    if is_at_rule {
153	                        at_rule_context.push(rule.id());
154	                        // Push a sentinel so we pop after this subtree is processed.
155	                        stack.push(Frame::PopAtRule);
156	                    }
157	
158	                    // Push children in reverse order so they process left-to-right.
159	                    for child_id in rule.child_ids().iter().rev() {
160	                        stack.push(Frame::Visit(*child_id));
161	                    }
162	
163	                    // For qualified rules with selectors, check for duplicates.
164	                    if !is_at_rule && !rule.selectors().is_empty() {
165	                        let mut normalized_selectors: Vec<String> = rule
166	                            .selectors()
167	                            .iter()
168	                            .map(|s| s.resolved().normalize())
169	                            .collect();
170	                        normalized_selectors.sort();
171	
172	                        let list_key = normalized_selectors.join(", ");
173	                        let context_key = (at_rule_context.clone(), list_key.clone());
174	                        let rule_range = rule.range(&root);
175	
176	                        match seen.get(&context_key) {
177	                            Some(&first_range) => {
178	                                duplicates.push(DuplicateSelectorList {
179	                                    duplicate_range: rule_range,
180	                                    first_range,
181	                                    normalized_list: list_key,
182	                                });
183	                            }
184	                            None => {
185	                                seen.insert(context_key, rule_range);
186	                            }
187	                        }
188	                    }
189	                }
190	            }
191	        }
192	
193	        duplicates.into_boxed_slice()
194	    }
