11	pub(crate) const ID_SPECIFICITY: Specificity = Specificity(1, 0, 0);
12	pub(crate) const CLASS_SPECIFICITY: Specificity = Specificity(0, 1, 0);
13	pub(crate) const TYPE_SPECIFICITY: Specificity = Specificity(0, 0, 1);
14	pub(crate) const ZERO_SPECIFICITY: Specificity = Specificity(0, 0, 0);
15	
16	fn evaluate_any_simple_selector(selector: &AnyCssSimpleSelector) -> Specificity {
17	    match selector {
18	        AnyCssSimpleSelector::CssTypeSelector(_) => TYPE_SPECIFICITY,
19	        AnyCssSimpleSelector::CssUniversalSelector(_) => ZERO_SPECIFICITY,
20	        AnyCssSimpleSelector::ScssPlaceholderSelector(_) => CLASS_SPECIFICITY,
21	    }
22	}
23	
24	/// See https://developer.mozilla.org/en-US/docs/Web/CSS/Specificity#the_is_not_has_and_css_nesting_exceptions
25	const fn evaluate_pseudo_function_selector(name: &str) -> Option<Specificity> {
26	    match name.as_bytes() {
27	        b"where" => None,
28	        b"is" | b"not" | b"has" | b"matches" => Some(ZERO_SPECIFICITY),
29	        _ => Some(CLASS_SPECIFICITY),
30	    }
31	}
32	
33	fn evaluate_any_pseudo_class(class: &AnyCssPseudoClass) -> Specificity {
34	    // https://www.w3.org/TR/selectors-4/#specificity-rules
35	    match class {
36	        AnyCssPseudoClass::CssBogusPseudoClass(_) => ZERO_SPECIFICITY,
37	        AnyCssPseudoClass::CssPseudoClassFunctionCompoundSelector(selector) => {
38	            CLASS_SPECIFICITY
39	                + selector
40	                    .selector()
41	                    .map_or(ZERO_SPECIFICITY, |s| evaluate_any_compound_selector(&s))
42	        }
43	        AnyCssPseudoClass::CssPseudoClassFunctionCompoundSelectorList(selector_list) => {
44	            let list_max = selector_list
45	                .compound_selectors()
46	                .iter()
47	                .map(|s| s.map_or(ZERO_SPECIFICITY, |s| evaluate_any_compound_selector(&s)))
48	                .reduce(|acc, e| acc.max(e))
49	                .unwrap_or(ZERO_SPECIFICITY);
50	
51	            CLASS_SPECIFICITY + list_max
52	        }
53	        AnyCssPseudoClass::CssPseudoClassFunctionIdentifier(_) => CLASS_SPECIFICITY,
54	        AnyCssPseudoClass::CssPseudoClassFunctionNth(_) => CLASS_SPECIFICITY,
55	        AnyCssPseudoClass::CssPseudoClassFunctionRelativeSelectorList(selector_list) => {
56	            if let Some(base) = selector_list
57	                .name()
58	                .ok()
59	                .and_then(|name| name.value_token().ok())
60	                .and_then(|name| evaluate_pseudo_function_selector(name.text_trimmed()))
61	            {
62	                let list_max = selector_list
63	                    .relative_selectors()
64	                    .iter()
65	                    .map(|relative_selector| {
66	                        relative_selector
67	                            .map_or(ZERO_SPECIFICITY, |s| evaluate_any_relative_selector(&s))
68	                    })
69	                    .reduce(|acc, e| acc.max(e))
70	                    .unwrap_or(ZERO_SPECIFICITY);
71	                base + list_max
72	            } else {
73	                ZERO_SPECIFICITY
74	            }
75	        }
76	        AnyCssPseudoClass::CssPseudoClassFunctionSelector(s) => {
77	            if let Some(base) = s
78	                .name()
79	                .ok()
80	                .and_then(|name| name.value_token().ok())
81	                .and_then(|name| evaluate_pseudo_function_selector(name.text_trimmed()))
82	            {
83	                base + s.selector().map_or(ZERO_SPECIFICITY, |selector| {
84	                    evaluate_any_selector(&selector)
85	                })
86	            } else {
87	                ZERO_SPECIFICITY
88	            }
89	        }
90	        AnyCssPseudoClass::CssPseudoClassFunctionSelectorList(selector_list) => {
91	            if let Some(base) = selector_list
92	                .name()
93	                .ok()
94	                .and_then(|name| name.value_token().ok())
95	                .and_then(|name| evaluate_pseudo_function_selector(name.text_trimmed()))
96	            {
97	                let list_max = selector_list
98	                    .selectors()
99	                    .iter()
100	                    .map(|selector| {
101	                        selector.map_or(ZERO_SPECIFICITY, |s| evaluate_any_selector(&s))
102	                    })
103	                    .reduce(|acc, e| acc.max(e))
104	                    .unwrap_or(ZERO_SPECIFICITY);
105	                base + list_max
106	            } else {
107	                ZERO_SPECIFICITY
108	            }
109	        }
110	        AnyCssPseudoClass::CssPseudoClassFunctionValueList(_) => CLASS_SPECIFICITY,
111	        AnyCssPseudoClass::CssPseudoClassIdentifier(_) => CLASS_SPECIFICITY,
112	        AnyCssPseudoClass::CssPseudoClassFunctionCustomIdentifier(_) => CLASS_SPECIFICITY,
113	        AnyCssPseudoClass::CssPseudoClassFunctionCustomIdentifierList(_) => CLASS_SPECIFICITY,
114	    }
115	}
116	
117	fn evaluate_pseudo_selector(selector: &CssPseudoClassSelector) -> Specificity {
118	    match selector.class() {
119	        Ok(any_pseudo_class) => evaluate_any_pseudo_class(&any_pseudo_class),
120	        Err(_) => ZERO_SPECIFICITY,
121	    }
122	}
