124	fn evaluate_any_subselector(selector: &AnyCssSubSelector) -> Specificity {
125	    // https://www.w3.org/TR/selectors-4/#typedef-subclass-selector
126	    match selector {
127	        AnyCssSubSelector::CssIdSelector(_) => ID_SPECIFICITY,
128	        AnyCssSubSelector::CssClassSelector(_) => CLASS_SPECIFICITY,
129	        AnyCssSubSelector::CssAttributeSelector(_) => CLASS_SPECIFICITY,
