use biome_console::markup;
use biome_css_syntax::{
    AnyCssRelativeSelector, CssNestedQualifiedRule, CssQualifiedRule, CssSyntaxKind,
};
use biome_rowan::{AstNode, AstNodeList, AstSeparatedList, SyntaxNodeCast, TextRange, declare_node_union};

use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;

declare_lint_rule! {
    /// Disallow selectors with too many class selectors.
    ///
    /// Selectors that chain many class selectors together are harder to read,
    /// override, and reuse. This rule flags any individual selector whose total
    /// number of class selectors exceeds the configured maximum.
    ///
    /// Class selectors are counted across the whole selector, including those
    /// nested inside pseudo-class functions such as `:not()`, `:is()`, `:has()`,
    /// and `:nth-child(... of ...)`.
    ///
    /// Each selector in a comma-separated selector list is evaluated on its own,
    /// and nested selectors are evaluated independently from their parent.
    ///
    /// This rule is only active when the `maxClasses` option is configured.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// The following example will show a diagnostic when `maxClasses` is set to 1:
    ///
    /// ```json,options
    /// {
    ///     "options": {
    ///        "maxClasses": 1
    ///     }
    /// }
    /// ```
    /// ```css,expect_diagnostic,use_options
    /// .foo.bar {}
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css,use_options
    /// .foo {}
    /// ```
    ///
    /// ## Options
    ///
    /// ### `maxClasses`
    ///
    /// This option sets the maximum number of class selectors allowed in a single
    /// selector. When it is not set, the rule does not report any diagnostics.
    ///
    pub NoExcessiveSelectorClasses {
        version: "next",
        name: "noExcessiveSelectorClasses",
        language: "css",
        recommended: false,
    }
}

declare_node_union! {
    pub AnyCssRuleWithSelectors = CssQualifiedRule | CssNestedQualifiedRule
}

/// A single offending selector along with its class selector count.
#[derive(Debug)]
pub struct RuleState {
    /// Range of the offending selector.
    range: TextRange,
    /// Number of class selectors found in the selector.
    count: u16,
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssRuleWithSelectors>;
    type State = RuleState;
    type Signals = Box<[Self::State]>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let Some(max_classes) = ctx.options().max_classes else {
            return Box::new([]);
        };

        let node = ctx.query();
        let mut signals = Vec::new();

        for selector in node.selector_ranges() {
            // SCSS selectors with interpolation are dynamic, so we can't
            // reliably count their class selectors.
            if selector
                .descendants()
                .any(|n| n.kind() == CssSyntaxKind::SCSS_INTERPOLATION)
            {
                continue;
            }

            let count = selector
                .descendants()
                .filter(|n| n.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
                .count();

            let count = u16::try_from(count).unwrap_or(u16::MAX);
            if count > max_classes {
                signals.push(RuleState {
                    range: selector.text_range_with_trivia(),
                    count,
                });
            }
        }

        signals.into_boxed_slice()
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let max_classes = ctx.options().max_classes?;
        let found = state.count;

        let message = if max_classes == 1 {
            markup! {
                "Expected this selector to have no more than "{max_classes.to_string()}" class selector, but found "{found.to_string()}"."
            }
            .to_owned()
        } else {
            markup! {
                "Expected this selector to have no more than "{max_classes.to_string()}" class selectors, but found "{found.to_string()}"."
            }
            .to_owned()
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, message)
                .note(markup! {
                    "Selectors with too many chained classes are harder to read, override, and reuse."
                })
                .note(markup! {
                    "Reduce the number of class selectors in this selector, or split it into simpler selectors."
                }),
        )
    }
}

impl AnyCssRuleWithSelectors {
    /// Returns the syntax node of each top-level selector in this rule.
    fn selector_ranges(&self) -> Vec<biome_css_syntax::CssSyntaxNode> {
        match self {
            AnyCssRuleWithSelectors::CssQualifiedRule(rule) => rule
                .prelude()
                .into_iter()
                .filter_map(|selector| selector.ok())
                .map(|selector| selector.into_syntax())
                .collect(),
            AnyCssRuleWithSelectors::CssNestedQualifiedRule(rule) => rule
                .prelude()
                .iter()
                .filter_map(|selector| selector.ok())
                .filter_map(|selector| match selector {
                    AnyCssRelativeSelector::CssRelativeSelector(selector) => {
                        Some(selector.into_syntax())
                    }
                    AnyCssRelativeSelector::CssBogusSelector(_) => None,
                })
                .collect(),
        }
    }
}
